import{_ as t,o as a,c as i,a3 as r}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"Binary Flow Stabilizer","description":"","frontmatter":{"translationSource":{"title":"二进制稳流器","archivedAt":"2026-11-23","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=XZVY2YJV9J2aDl6ik1qPtM","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/binary-flow-stabilizer"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/binary-flow-stabilizer"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/binary-flow-stabilizer"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/binary-flow-stabilizer"}]]},"headers":[],"relativePath":"binary-flow-stabilizer.md","filePath":"logistics/src/page-XZVY2YJV9J2aDl6ik1qPtM.md"}'),o={name:"binary-flow-stabilizer.md"};function n(l,e,s,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<div class="logistics-content"><h1 id="binary-flow-stabilizer" tabindex="-1">Binary Flow Stabilizer <a class="header-anchor" href="#binary-flow-stabilizer" aria-label="Permalink to &quot;Binary Flow Stabilizer&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>Content updated: </span><a href="/endfield-skydoc/changelog/capture-2026-11-23T06-44-45-722Z-4358a738" title="Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record." aria-label="Content updated: 2026-11-23. Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record."><time datetime="2026-11-23T06:44:47.018Z">2026-11-23</time></a><span class="page-updated-zone"> (China Standard Time)</span></p><blockquote><p>Source page ID: <code>XZVY2YJV9J2aDl6ik1qPtM</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=XZVY2YJV9J2aDl6ik1qPtM" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>For details, see <a href="/endfield-skydoc/proof-of-the-minimum-configured-power-for-binary-flow-stabilizer-power">Proof of the Minimum Configured Power for Binary-Flow-Stabilizer Power Control</a>.</p><p>Structure: 24/25 rate limiting + uniform binary splitting + three-way splitting.</p><p>The <a href="/endfield-skydoc/error-propagation-in-serial-structures">Error Propagation in Serial Structures</a> gives this structure&#39;s theoretical maximum error. The <a href="/endfield-skydoc/calculating-the-range-of-stored-energy">Calculating the Range of Stored Energy</a> then gives its maximum energy range, determining whether outages can occur.</p><p>Advantages: calculable energy range, precise power control without waste, controllable structure, simple design.</p><p>Disadvantages: large footprint, cumbersome calculations, generation fixed by structure rather than automatically variable.</p><p>Common constructions for each part:</p><p><strong>24/25 rate limiting</strong></p><p><a href="/endfield-skydoc/applications-of-some-theories">Applications of Some Theories</a></p><p>Output-lag (“4n, 1 s stall”) implementation, error (n-1)/4n=(3-1)/4*3=1/6.</p><p><strong>Uniform binary</strong></p><p><a href="/endfield-skydoc/tianshi-academy-and-chishi-academy-of-sciences-online-documentation">Tianshi Academy and Chishi Academy of Sciences Online Documentation</a>. Its error is the <a href="/endfield-skydoc/theoretical-lower-bound-for-perfect-uniformity">theoretical lower bound for perfect uniformity</a>.</p><p>Quick calculation: 3200<em>40</em>0.5<em>24/25</em>p*1/3=x; uniform-binary ratio p=remaining demand/generation x/(5x2^12).</p><p><strong>Three-way splitting</strong></p><p>A three-output splitter divides into three, with error 0.</p><p>Using 24/25 output lag, the device has error M_dev &lt; 6(K-2)/(K-1); conjecturally the error should be &lt;1.</p><p>Translation note: The source&#39;s arithmetic notation, including (3-1)/4*3=1/6 and the quick-calculation expression, is retained without silently resolving its ambiguity.</p></div>',1)])])}const f=t(o,[["render",n]]);export{u as __pageData,f as default};
